/* Colestasis Neo — service worker (offline-first)
   Dr. Jano Jaramillo · v1.1 · nov 2026 */
const VERSION = "colestasis-neo-v1.1.0";
const SHELL = ["./", "./index.html"];
const FONT_HOSTS = ["fonts.googleapis.com", "fonts.gstatic.com"];

const ICON180 = "";
const ICON512 = "";
const MANIFEST = {
  name: "Colestasis Neonatal — CDSS",
  short_name: "Colestasis Neo",
  description: "Apoyo a la decisión clínica en colestasis neonatal: diagnóstico, fenotipos y tratamiento.",
  start_url: "./",
  scope: "./",
  display: "standalone",
  orientation: "portrait",
  background_color: "#0e1c16",
  theme_color: "#0e1c16",
  lang: "es",
  icons: [
    { src: "./icon-180.png", sizes: "180x180", type: "image/png" },
    { src: "./icon-512.png", sizes: "512x512", type: "image/png", purpose: "any maskable" }
  ]
};

function b64ToBytes(b64){ const bin = atob(b64); const u = new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) u[i]=bin.charCodeAt(i); return u; }
function virtual(path){
  if(path.endsWith("/manifest.webmanifest")) return new Response(JSON.stringify(MANIFEST), {headers:{"Content-Type":"application/manifest+json"}});
  if(path.endsWith("/icon-180.png")) return new Response(b64ToBytes(ICON180), {headers:{"Content-Type":"image/png"}});
  if(path.endsWith("/icon-512.png")) return new Response(b64ToBytes(ICON512), {headers:{"Content-Type":"image/png"}});
  return null;
}

self.addEventListener("install", e => {
  e.waitUntil(caches.open(VERSION).then(c => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", e => {
  e.waitUntil(
    caches.keys().then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", e => {
  const req = e.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);

  // Archivos virtuales (manifiesto e íconos) servidos desde el propio SW
  if (url.origin === self.location.origin) {
    const v = virtual(url.pathname);
    if (v) { e.respondWith(Promise.resolve(v)); return; }
  }

  // Fuentes de Google: stale-while-revalidate
  if (FONT_HOSTS.includes(url.hostname)) {
    e.respondWith(caches.open(VERSION).then(async c => {
      const hit = await c.match(req);
      const net = fetch(req).then(r => { if (r && (r.ok || r.type === "opaque")) c.put(req, r.clone()); return r; }).catch(() => hit);
      return hit || net;
    }));
    return;
  }

  if (url.origin !== self.location.origin) return;

  // Navegación: red primero (para recibir actualizaciones), caché si no hay red
  if (req.mode === "navigate") {
    e.respondWith(
      fetch(req).then(r => { const cp = r.clone(); caches.open(VERSION).then(c => c.put("./index.html", cp)); return r; })
        .catch(() => caches.match("./index.html").then(r => r || caches.match("./")))
    );
    return;
  }

  // Resto del mismo origen: caché primero
  e.respondWith(
    caches.match(req).then(hit => hit || fetch(req).then(r => {
      if (r && r.ok) { const cp = r.clone(); caches.open(VERSION).then(c => c.put(req, cp)); }
      return r;
    }))
  );
});
